import React, { useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import type { AppPreferences, CalendarEvent, DashboardSnapshot, EmailDraft, EntityKind, InboxMessage, InvoiceDraft, ModuleId, RecordItem, TeamMember } from "@shared/contracts";
import "@fontsource-variable/inter";
import "@fontsource-variable/jetbrains-mono";
import "@fontsource/noto-sans-arabic";
import "../styles/mission-control.css";

type Toast = { tone: "success" | "warning" | "error"; text: string } | null;
const rail: Array<{ id: ModuleId; label: string; icon: string }> = [
  { id: "home", label: "Home", icon: "⌂" }, { id: "copilot", label: "Copilot", icon: "✦" }, { id: "inbox", label: "Inbox", icon: "⌁" },
  { id: "calendar", label: "Calendar", icon: "▦" }, { id: "leads", label: "Leads", icon: "◈" }, { id: "customers", label: "Customers", icon: "◎" },
  { id: "jobs", label: "Jobs", icon: "▣" }, { id: "money", label: "Money", icon: "◇" }, { id: "reports", label: "Reports", icon: "◒" },
  { id: "team", label: "Team", icon: "◌" }, { id: "settings", label: "Settings", icon: "⚙" }
];
const title: Record<ModuleId, string> = { home: "Command Center", copilot: "Ask Tasko", inbox: "Inbox", calendar: "Calendar", leads: "Leads", customers: "Customers", jobs: "Jobs & tasks", money: "Money", reports: "Reports", team: "Team", settings: "Settings" };
const kindForModule: Partial<Record<ModuleId, EntityKind>> = { leads: "lead", customers: "customer", jobs: "job", money: "invoice" };
const formatMoney = (amount = 0, currency = "AED") => new Intl.NumberFormat("en-AE", { style: "currency", currency, maximumFractionDigits: 0 }).format(amount);
const shortDate = (value?: string | null) => value ? new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "short" }).format(new Date(value)) : "—";
const toDateTimeInput = (value: Date) => new Date(value.getTime() - value.getTimezoneOffset() * 60_000).toISOString().slice(0, 16);

type AppointmentDraft = { title: string; subtitle?: string; startAt: string; endAt: string; assignee?: string; travelMinutes: number };

function App() {
  const [ready, setReady] = useState(false);
  const [preferences, setPreferences] = useState<AppPreferences>();
  const [dashboard, setDashboard] = useState<DashboardSnapshot>();
  const [active, setActive] = useState<ModuleId>("home");
  const [inspector, setInspector] = useState<RecordItem | null>(null);
  const [palette, setPalette] = useState(false);
  const [quickCapture, setQuickCapture] = useState(false);
  const [toast, setToast] = useState<Toast>(null);
  const [version, setVersion] = useState("");
  const [tabs, setTabs] = useState<Array<{ id: string; label: string }>>([{ id: "home", label: "Home" }]);

  const refresh = async () => {
    const next = await window.tasko.bootstrap();
    setPreferences(next.preferences); setDashboard(next.dashboard); setVersion(next.version); setReady(true);
    void window.tasko.system.setBadge(next.dashboard.overdue);
  };
  useEffect(() => { void refresh().catch((error: Error) => setToast({ tone: "error", text: error.message })); }, []);
  useEffect(() => {
    const keydown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setPalette(true); }
      if ((event.metaKey || event.ctrlKey) && event.shiftKey && event.key.toLowerCase() === "n") { event.preventDefault(); setQuickCapture(true); }
      if (event.key === "Escape") { setPalette(false); setQuickCapture(false); }
    };
    window.addEventListener("keydown", keydown); return () => window.removeEventListener("keydown", keydown);
  }, []);
  useEffect(() => { const timer = toast ? window.setTimeout(() => setToast(null), 4200) : undefined; return () => { if (timer) window.clearTimeout(timer); }; }, [toast]);

  const navigate = (next: ModuleId) => { setActive(next); setInspector(null); if (!tabs.some((tab) => tab.id === next)) setTabs((old) => [...old, { id: next, label: title[next] }]); };
  const open = (record: RecordItem) => { setInspector(record); const id = `${active}-${record.id}`; if (!tabs.some((tab) => tab.id === id)) setTabs((old) => [...old, { id, label: record.title }]); };
  const fail = (error: unknown) => setToast({ tone: "error", text: error instanceof Error ? error.message : "That action could not be completed." });

  if (!ready || !preferences || !dashboard) return <Splash />;
  if (!preferences.setupComplete) return <Welcome onComplete={async (value) => { try { await window.tasko.preferences.completeSetup(value); await refresh(); } catch (error) { fail(error); } }} onSignIn={() => void window.tasko.system.signInToSync()} />;

  return <main className={`app density-${preferences.density} ${preferences.theme === "light" ? "theme-light" : ""}`} dir={preferences.locale === "ar" ? "rtl" : "ltr"}>
    <aside className="icon-rail" aria-label="Primary navigation">
      <button className="brand" title="Tasko home" onClick={() => navigate("home")}><i>t</i></button>
      <nav>{rail.map((item) => <button key={item.id} className={active === item.id ? "active" : ""} title={item.label} aria-label={item.label} onClick={() => navigate(item.id)}><span>{item.icon}</span></button>)}</nav>
      <button className="rail-bottom" title="Quick capture" onClick={() => setQuickCapture(true)}>＋</button>
    </aside>
    <aside className="context-sidebar">
      <div className="workspace-switcher"><span className="status-dot" /> <b>{preferences.businessName || "This computer"}</b><button aria-label="Workspace menu">⌄</button></div>
      <div className="side-search"><span>⌘K</span><button onClick={() => setPalette(true)}>Search everything</button></div>
      <div className="side-section"><p>WORKSPACE</p>{rail.slice(active === "home" ? 3 : 0, active === "home" ? 9 : 3).map((item) => <button className={item.id === active ? "selected" : ""} onClick={() => navigate(item.id)} key={item.id}>{item.icon} <span>{item.label}</span></button>)}</div>
      <div className="side-section grow"><p>PINNED</p><button onClick={() => navigate("calendar")}>◷ <span>Today’s schedule</span></button><button onClick={() => navigate("leads")}>◎ <span>Follow-up queue</span></button><button onClick={() => navigate("money")}>◇ <span>Draft invoices</span></button></div>
      <div className="connection-card"><span className="pulse" /> Working locally <small>Sync is optional</small></div>
    </aside>
    <section className="workspace">
      <header className="window-header">
        <div className="tab-strip">{tabs.map((tab) => <button key={tab.id} className={tab.id === active || tab.id.startsWith(`${active}-`) ? "tab active" : "tab"} onClick={() => { const module = rail.find((item) => item.id === tab.id)?.id; if (module) navigate(module); }}>{tab.label}<span onClick={(event) => { event.stopPropagation(); setTabs((old) => old.filter((item) => item.id !== tab.id)); }}>×</span></button>)}<button className="new-tab" onClick={() => setPalette(true)}>＋</button></div>
        <div className="header-actions"><button className="shortcut-button" onClick={() => setPalette(true)}>⌘ K</button><button className="ghost-action" onClick={() => setInspector(inspector ? null : { id: "overview", title: "Workspace details", status: "healthy", createdAt: "", updatedAt: "" })}>◧</button></div>
      </header>
      <section className="content"><Page active={active} dashboard={dashboard} preferences={preferences} onNavigate={navigate} onOpen={open} notify={setToast} refresh={refresh} /></section>
      <footer className="statusbar"><span><i className="online" /> Local database</span><span>Offline-ready</span><span>{version ? `v${version}` : "Version unavailable"}</span><span>{dashboard.overdue} overdue</span><button onClick={() => void window.tasko.system.checkForUpdates().then((result) => setToast({ tone: "success", text: `${result.status}${result.detail ? ` · ${result.detail}` : ""}` })).catch(fail)}>Check updates</button></footer>
    </section>
    {inspector && <Inspector record={inspector} active={active} onClose={() => setInspector(null)} notify={setToast} onRefresh={refresh} />}
    {palette && <CommandPalette onClose={() => setPalette(false)} onNavigate={navigate} onOpen={open} />}
    {quickCapture && <QuickCapture onClose={() => setQuickCapture(false)} onDone={async () => { setQuickCapture(false); await refresh(); setToast({ tone: "success", text: "Saved to your local workspace." }); }} />}
    {toast && <div className={`toast ${toast.tone}`}>{toast.tone === "success" ? "✓" : toast.tone === "warning" ? "!" : "×"} {toast.text}</div>}
  </main>;
}

function Splash() { return <main className="splash"><div className="splash-mark"><i>t</i></div><span className="splash-kicker">TASKO DESKTOP</span><h1>Tasko</h1><p>Opening your local workspace</p><span className="progress"><b /></span></main>; }

function Welcome({ onComplete, onSignIn }: { onComplete(value: Pick<AppPreferences, "businessName" | "locale" | "currency" | "backupFolder">): Promise<void>; onSignIn(): void }) {
  const [step, setStep] = useState(0); const [name, setName] = useState(""); const [locale, setLocale] = useState<"en" | "ar">("en"); const [currency, setCurrency] = useState<AppPreferences["currency"]>("AED"); const [backupFolder, setBackupFolder] = useState("");
  const labels = ["Workspace", "Work style", "Regional", "Backups"];
  const chooseFolder = async () => { const value = await window.tasko.system.chooseBackupFolder(); if (value) setBackupFolder(value); };
  return <main className="welcome">
    <header className="welcome-top"><div className="brand-wide"><i>t</i><span>tasko</span></div><div className="welcome-top-meta"><span className="desktop-pill">DESKTOP</span><span><i className="online" /> This Mac</span></div></header>
    {step === 0 ? <section className="welcome-intro"><div className="welcome-copy"><span className="eyebrow">TASKO DESKTOP</span><h1>Work stays<br />in <em>one place.</em></h1><p>A focused desktop workspace for customers, tasks, appointments, and invoices—built to work even when the internet does not.</p><div className="welcome-actions"><button className="primary" onClick={() => setStep(1)}>Set up Tasko <span>→</span></button><button className="secondary-action" onClick={onSignIn}>Sign in to sync <span>↗</span></button></div><div className="welcome-trust"><span>Local database</span><span>Offline-ready</span><span>No required account</span></div></div><aside className="welcome-preview" aria-label="Tasko desktop preview"><header><span>THIS MAC</span><b><i className="online" /> Private workspace</b></header><div className="preview-title"><span>Today</span><strong>Start with a clear desk.</strong><p>Your calendar, customer work, and documents live together here.</p></div><div className="preview-stack"><article><b>01</b><div><strong>Customer work</strong><small>Private records, ready when you are</small></div><i>→</i></article><article><b>02</b><div><strong>Today’s schedule</strong><small>Appointments with conflict checks</small></div><i>→</i></article><article><b>03</b><div><strong>Money, simplified</strong><small>Local invoices and PDF output</small></div><i>→</i></article></div><footer><span>⌘ K to search</span><span>Tasko v0.1</span></footer></aside></section> : <section className="setup"><header className="setup-header"><div><span className="eyebrow">SETUP</span><h1>Make Tasko yours.</h1><p>Four short choices. Everything remains editable later.</p></div><div className="setup-progress" aria-label={`Setup step ${step} of 4`}>{labels.map((label, index) => <div className={index <= step - 1 ? "done" : ""} key={label}><b>{index + 1}</b><span>{label}</span></div>)}</div></header><div className="setup-card">{step === 1 && <><span className="eyebrow">01 — WORKSPACE</span><h2>What should we call this workspace?</h2><p>This name stays on this Mac and appears on locally created documents.</p><label>Business name<input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder="e.g. Northline Studio" /></label></>}{step === 2 && <><span className="eyebrow">02 — WORK STYLE</span><h2>Start with the essentials.</h2><p>Tasko is ready for the work in front of you. Add services, people, and appointments as you go.</p><div className="setup-note"><i>⌘</i><span>Your calendar begins in this device’s timezone.</span></div></>}{step === 3 && <><span className="eyebrow">03 — REGIONAL</span><h2>Set your local defaults.</h2><p>These settings shape dates, money, and document language. You can change them anytime.</p><div className="two-inputs"><label>Language<select value={locale} onChange={(event) => setLocale(event.target.value as "en" | "ar")}><option value="en">English</option><option value="ar">العربية</option></select></label><label>Currency<select value={currency} onChange={(event) => setCurrency(event.target.value as AppPreferences["currency"])}>{["AED", "USD", "EUR", "GBP", "SAR"].map((code) => <option key={code}>{code}</option>)}</select></label></div></>}{step === 4 && <><span className="eyebrow">04 — BACKUPS</span><h2>Choose where backup copies live.</h2><p>Tasko creates a local copy before database upgrades and whenever you request one.</p><button className="folder-picker" onClick={() => void chooseFolder()}>⌘ <span>{backupFolder || "Choose backup location"}</span><b>Browse</b></button><div className="setup-note"><i>✓</i><span>Your workspace is private by default. Syncing is always a separate choice.</span></div></>}<div className="setup-actions"><button className="text-button" onClick={() => step === 1 ? setStep(0) : setStep(step - 1)}>Back</button><button className="primary" disabled={step === 1 && !name.trim()} onClick={() => step < 4 ? setStep(step + 1) : void onComplete({ businessName: name.trim(), locale, currency, backupFolder: backupFolder || undefined })}>{step === 4 ? "Open Tasko" : "Continue"} <span>→</span></button></div></div></section>}
  </main>;
}

function Page({ active, dashboard, preferences, onNavigate, onOpen, notify, refresh }: { active: ModuleId; dashboard: DashboardSnapshot; preferences: AppPreferences; onNavigate(next: ModuleId): void; onOpen(item: RecordItem): void; notify(value: Toast): void; refresh(): Promise<void> }) {
  if (active === "home") return <Home dashboard={dashboard} preferences={preferences} onNavigate={onNavigate} onOpen={onOpen} />;
  if (active === "copilot") return <Copilot notify={notify} />;
  if (active === "inbox") return <Inbox notify={notify} />;
  if (active === "calendar") return <Calendar onOpen={onOpen} notify={notify} refresh={refresh} />;
  if (active === "team") return <Team notify={notify} />;
  if (active === "money") return <Money onOpen={onOpen} notify={notify} refresh={refresh} />;
  if (["leads", "customers", "jobs"].includes(active)) return <Records module={active} onOpen={onOpen} notify={notify} refresh={refresh} />;
  if (active === "reports") return <Reports dashboard={dashboard} />;
  if (active === "settings") return <Settings preferences={preferences} notify={notify} refresh={refresh} />;
  return <ModulePlaceholder active={active} />;
}

function Home({ dashboard, preferences, onNavigate, onOpen }: { dashboard: DashboardSnapshot; preferences: AppPreferences; onNavigate(next: ModuleId): void; onOpen(item: RecordItem): void }) {
  const [command, setCommand] = useState(""); const [results, setResults] = useState<Array<RecordItem & { kind: EntityKind }>>([]);
  const search = async (value: string) => { setCommand(value); setResults(value.trim() ? await window.tasko.records.search(value) : []); };
  return <div className="command-center"><header className="page-heading"><div><span className="eyebrow">{dashboard.date}</span><h1>{dashboard.greeting} <span>✦</span></h1></div><div className="weather">Dubai <b>31°</b><span>Clear</span></div></header><section className="command-hero"><div className="command-input"><span>✦</span><input autoFocus placeholder="Ask Tasko or type a command" value={command} onChange={(event) => void search(event.target.value)} /><kbd>⌘ K</kbd></div>{results.length > 0 && <div className="command-results">{results.map((item) => <button key={item.id} onClick={() => onOpen(item)}><span>{item.kind}</span><b>{item.title}</b><small>{item.subtitle}</small></button>)}</div>}<div className="quick-capture-row"><button onClick={() => onNavigate("calendar")}>＋ Schedule</button><button onClick={() => onNavigate("leads")}>＋ Lead</button><button onClick={() => onNavigate("money")}>＋ Invoice</button><button onClick={() => onNavigate("jobs")}>＋ Task</button></div></section><section className="home-grid"><article className="attention panel"><div className="panel-title"><div><span className="eyebrow">FOCUS QUEUE</span><h2>Needs your attention</h2></div><button onClick={() => onNavigate("jobs")}>See all →</button></div>{dashboard.attention.length ? dashboard.attention.map((item) => <button className="attention-item" key={item.id} onClick={() => onNavigate("jobs")}><i>!</i><span><b>{item.label}</b><small>{item.kind} · due {shortDate(item.dueAt)}</small></span><em>→</em></button>) : <Empty label="Your attention queue is clear" detail="Tasko will surface urgent local work here." />}</article><article className="today panel"><div className="panel-title"><div><span className="eyebrow">TODAY</span><h2>Timeline</h2></div><button onClick={() => onNavigate("calendar")}>Open calendar →</button></div><div className="timeline">{dashboard.timeline.length ? dashboard.timeline.map((event) => <button key={event.id} onClick={() => onNavigate("calendar")}><time>{new Intl.DateTimeFormat("en-GB", { hour: "2-digit", minute: "2-digit" }).format(new Date(event.startAt))}</time><i /><span><b>{event.title}</b><small>{event.travelMinutes ? `${event.travelMinutes} min travel · ` : ""}{event.assignee || "Unassigned"}</small></span></button>) : <Empty label="No visits booked today" detail="Add an appointment from Calendar." />}</div></article><article className="metrics panel"><div className="panel-title"><div><span className="eyebrow">LOCAL SNAPSHOT</span><h2>At a glance</h2></div></div><div className="metric-grid">{Object.entries(dashboard.counts).map(([label, value]) => <button key={label} onClick={() => onNavigate(label === "customers" ? "customers" : label === "leads" ? "leads" : label === "invoices" ? "money" : "jobs")}><strong>{value}</strong><span>{label}</span></button>)}</div></article></section></div>;
}

function Inbox({ notify }: { notify(value: Toast): void }) {
  const [messages, setMessages] = useState<InboxMessage[]>([]); const [composer, setComposer] = useState(false); const [removing, setRemoving] = useState<string | null>(null);
  const load = async () => setMessages(await window.tasko.inbox.list());
  useEffect(() => { void load(); }, []);
  const create = async (draft: EmailDraft) => { try { await window.tasko.inbox.create(draft); await load(); setComposer(false); notify({ tone: "success", text: "Email draft saved only on this computer." }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Email draft could not be saved." }); } };
  const openInEmail = async (message: InboxMessage) => { try { await window.tasko.inbox.openInEmail(message.id); await load(); notify({ tone: "success", text: "Your email app opened. Sending stays under your control." }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Could not open your email app." }); } };
  const remove = async (message: InboxMessage) => { try { await window.tasko.inbox.remove(message.id); await load(); setRemoving(null); notify({ tone: "success", text: "Local email draft removed." }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Email draft could not be removed." }); } };
  return <div className="module-page inbox-page"><header className="page-heading"><div><span className="eyebrow">LOCAL MESSAGE DRAFTS</span><h1>Inbox</h1><p>Draft customer messages privately, then open them in your email app only when you are ready.</p></div><button className="primary" onClick={() => setComposer(true)}>＋ New message</button></header>{composer && <EmailComposer onCancel={() => setComposer(false)} onSave={create} />}<section className="inbox-list">{messages.length ? messages.map((message) => <article className="inbox-message panel" key={message.id}><div className="inbox-message-head"><div><span className="eyebrow">TO {message.recipient}</span><h2>{message.subject}</h2></div><em className={`status ${message.status}`}>{message.status === "opened" ? "opened in email" : "local draft"}</em></div><p>{message.body}</p><footer><small>{message.status === "opened" ? `Opened ${shortDate(message.openedAt)}` : `Saved ${shortDate(message.updatedAt)}`}</small><div>{removing === message.id ? <><button onClick={() => setRemoving(null)}>Keep draft</button><button className="danger-action" onClick={() => void remove(message)}>Remove permanently</button></> : <><button onClick={() => void openInEmail(message)}>Open in email app ↗</button><button onClick={() => setRemoving(message.id)}>Remove…</button></>}</div></footer></article>) : <div className="inbox-empty panel"><Empty label="No local message drafts" detail="Create a thoughtful customer email here. Tasko will keep it local until you choose to open your email app." /></div>}</section><p className="module-footnote">Tasko never sends email in the background and does not claim delivery after opening a draft in another app.</p></div>;
}

function EmailComposer({ onCancel, onSave }: { onCancel(): void; onSave(draft: EmailDraft): Promise<void> }) {
  const [recipient, setRecipient] = useState(""); const [subject, setSubject] = useState(""); const [body, setBody] = useState(""); const [saving, setSaving] = useState(false);
  const save = async () => { setSaving(true); try { await onSave({ recipient: recipient.trim(), subject: subject.trim(), body: body.trim() }); } finally { setSaving(false); } };
  return <section className="composer email-composer panel" aria-label="New email draft"><div className="composer-title"><div><span className="eyebrow">PRIVATE DRAFT</span><h2>New message</h2></div><button aria-label="Close new email draft" onClick={onCancel}>×</button></div><div className="email-grid"><label>Recipient<input autoFocus type="email" value={recipient} onChange={(event) => setRecipient(event.target.value)} placeholder="client@example.com" /></label><label>Subject<input value={subject} onChange={(event) => setSubject(event.target.value)} placeholder="A clear, helpful subject" /></label><label className="wide">Message<textarea value={body} onChange={(event) => setBody(event.target.value)} placeholder="Write your message…" rows={7} /></label></div><div className="composer-footer"><span>Saved locally first. Tasko will ask before opening your email app.</span><button className="primary" disabled={saving || !recipient.trim() || !subject.trim() || !body.trim()} onClick={() => void save()}>{saving ? "Saving…" : "Save draft"}</button></div></section>;
}

function Team({ notify }: { notify(value: Toast): void }) {
  const [members, setMembers] = useState<TeamMember[]>([]); const [composer, setComposer] = useState(false);
  const load = async () => setMembers(await window.tasko.team.list());
  useEffect(() => { void load(); }, []);
  const create = async (member: Omit<TeamMember, "id" | "createdAt" | "updatedAt">) => { try { await window.tasko.team.create(member); await load(); setComposer(false); notify({ tone: "success", text: "Team member stored in this local workspace." }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Team member could not be added." }); } };
  const setAvailability = async (member: TeamMember, status: TeamMember["status"]) => { try { await window.tasko.team.setAvailability(member.id, status); await load(); notify({ tone: "success", text: `${member.name} is now marked ${status}.` }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Availability could not be updated." }); } };
  const activeMembers = members.filter((member) => member.status === "active"); const weeklyCapacity = activeMembers.reduce((total, member) => total + member.capacity, 0);
  return <div className="module-page team-page"><header className="page-heading"><div><span className="eyebrow">LOCAL TEAM ROSTER</span><h1>Team</h1><p>Plan availability and capacity on this computer. Team syncing remains an explicit future choice.</p></div><button className="primary" onClick={() => setComposer(true)}>＋ Add member</button></header><section className="team-summary"><article><span>Active now</span><b>{activeMembers.length}</b><small>of {members.length} local members</small></article><article><span>Weekly capacity</span><b>{weeklyCapacity}h</b><small>from members marked available</small></article><article><span>Data location</span><b>Local</b><small>No roster is synced automatically</small></article></section>{composer && <TeamComposer onCancel={() => setComposer(false)} onSave={create} />}<section className="team-list">{members.map((member) => <article className="team-member panel" key={member.id}><div className="team-avatar">{member.name.slice(0, 1).toUpperCase()}</div><div className="team-member-main"><h2>{member.name}</h2><p>{member.email || "No email stored"}</p><div><em className={`status ${member.status}`}>{member.status}</em><span>{member.role}</span><span>{member.capacity}h weekly</span></div></div><button className={member.status === "active" ? "team-availability" : "team-availability available"} onClick={() => void setAvailability(member, member.status === "active" ? "away" : "active")}>{member.status === "active" ? "Mark away" : "Mark available"}</button></article>)}</section><p className="module-footnote">Availability is a local planning signal. It never changes anyone’s account or sends a notification.</p></div>;
}

function TeamComposer({ onCancel, onSave }: { onCancel(): void; onSave(member: Omit<TeamMember, "id" | "createdAt" | "updatedAt">): Promise<void> }) {
  const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [role, setRole] = useState<TeamMember["role"]>("staff"); const [capacity, setCapacity] = useState(40); const [status, setStatus] = useState<TeamMember["status"]>("active"); const [saving, setSaving] = useState(false);
  const save = async () => { setSaving(true); try { await onSave({ name: name.trim(), email: email.trim() || undefined, role, capacity: Math.max(1, Math.min(120, Number.isFinite(capacity) ? capacity : 40)), status }); } finally { setSaving(false); } };
  return <section className="composer team-composer panel" aria-label="Add local team member"><div className="composer-title"><div><span className="eyebrow">LOCAL ROSTER</span><h2>Add team member</h2></div><button aria-label="Close add team member" onClick={onCancel}>×</button></div><div className="team-grid"><label>Name<input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder="Team member name" /></label><label>Email (optional)<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="name@example.com" /></label><label>Role<select value={role} onChange={(event) => setRole(event.target.value as TeamMember["role"])}>{["owner", "admin", "manager", "staff"].map((value) => <option key={value}>{value}</option>)}</select></label><label>Weekly capacity<input type="number" min="1" max="120" value={capacity} onChange={(event) => setCapacity(Number(event.target.value))} /></label><label>Availability<select value={status} onChange={(event) => setStatus(event.target.value as TeamMember["status"])}><option value="active">Available</option><option value="away">Away</option></select></label></div><div className="composer-footer"><span>Roster data stays in local SQLite until you choose to sync it.</span><button className="primary" disabled={saving || !name.trim()} onClick={() => void save()}>{saving ? "Saving…" : "Add member"}</button></div></section>;
}

function Records({ module, onOpen, notify, refresh }: { module: ModuleId; onOpen(item: RecordItem): void; notify(value: Toast): void; refresh(): Promise<void> }) {
  const kind = kindForModule[module]!; const [rows, setRows] = useState<RecordItem[]>([]); const [query, setQuery] = useState(""); const [creating, setCreating] = useState(false); const [selected, setSelected] = useState<string[]>([]);
  const load = async (next = query) => setRows(await window.tasko.records.list(kind, next));
  useEffect(() => { void load(""); }, [kind]);
  const create = async (titleValue: string, subtitle: string) => { try { const item = await window.tasko.records.create(kind, { title: titleValue, subtitle, status: kind === "lead" ? "new" : "active" }); setCreating(false); await load(); onOpen(item); notify({ tone: "success", text: `${module === "leads" ? "Lead" : "Record"} created locally.` }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Could not create record." }); } };
  const convert = async (id: string) => { try { const result = await window.tasko.records.convertLead(id); await load(); await refresh(); notify({ tone: "success", text: `${result.title} is now a customer.` }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Could not convert lead." }); } };
  return <div className="module-page"><header className="page-heading"><div><span className="eyebrow">LOCAL {module.toUpperCase()}</span><h1>{title[module]}</h1><p>{module === "leads" ? "Move opportunities from first conversation to signed work." : module === "customers" ? "Every relationship, with a private local history." : "Coordinate work, assignments and deadlines."}</p></div><button className="primary" onClick={() => setCreating(true)}>＋ New {module === "jobs" ? "job" : module.slice(0, -1)}</button></header><div className="data-toolbar"><div className="table-search">⌕ <input placeholder={`Search ${module}`} value={query} onChange={(event) => { setQuery(event.target.value); void load(event.target.value); }} /></div><button>Filter</button><button>Saved view ⌄</button><span>{selected.length ? `${selected.length} selected` : `${rows.length.toLocaleString()} records`}</span></div>{creating && <InlineCreate label={module === "jobs" ? "job" : module.slice(0, -1)} onCancel={() => setCreating(false)} onSave={create} />}<div className="data-panel panel"><div className="table-head"><span><input aria-label="Select all" type="checkbox" checked={selected.length === rows.length && rows.length > 0} onChange={(event) => setSelected(event.target.checked ? rows.map((row) => row.id) : [])} /></span><span>Name</span><span>Status</span><span>Value</span><span>Updated</span></div><VirtualRows rows={rows} render={(row) => <div className={selected.includes(row.id) ? "table-row selected" : "table-row"} key={row.id}><span><input aria-label={`Select ${row.title}`} type="checkbox" checked={selected.includes(row.id)} onChange={() => setSelected((old) => old.includes(row.id) ? old.filter((value) => value !== row.id) : [...old, row.id])} /></span><button onClick={() => onOpen(row)}><b>{row.title}</b><small>{row.subtitle || "No detail"}</small></button><span><em className={`status ${row.status.replaceAll(" ", "-")}`}>{row.status}</em></span><span className="number">{row.amount ? formatMoney(row.amount, row.currency) : "—"}</span><span>{shortDate(row.updatedAt)}</span>{module === "leads" && row.status !== "converted" && <button className="row-action" onClick={() => void convert(row.id)}>Convert</button>}</div>} empty={<Empty label={`No ${module} yet`} detail="Create your first record or import a CSV file." />} /></div><p className="module-footnote">Tables keep smooth scrolling with up to 100,000 local records. CSV import and duplicate review are available from the customer actions menu.</p></div>;
}

function VirtualRows({ rows, render, empty }: { rows: RecordItem[]; render(item: RecordItem): React.ReactNode; empty: React.ReactNode }) {
  const [scroll, setScroll] = useState(0); const rowHeight = 61; const visible = 12; const start = Math.max(0, Math.floor(scroll / rowHeight) - 3); const end = Math.min(rows.length, start + visible + 6);
  if (!rows.length) return <div className="table-empty">{empty}</div>;
  return <div className="virtual-list" onScroll={(event) => setScroll(event.currentTarget.scrollTop)}><div style={{ height: rows.length * rowHeight, position: "relative" }}><div style={{ position: "absolute", top: start * rowHeight, left: 0, right: 0 }}>{rows.slice(start, end).map(render)}</div></div></div>;
}

function Calendar({ onOpen, notify, refresh }: { onOpen(item: RecordItem): void; notify(value: Toast): void; refresh(): Promise<void> }) {
  const [events, setEvents] = useState<CalendarEvent[]>([]); const [view, setView] = useState("week"); const [composer, setComposer] = useState(false); const load = async () => setEvents(await window.tasko.calendar.list()); useEffect(() => { void load(); }, []);
  const move = async (event: CalendarEvent, deltaHours: number) => { try { const start = new Date(new Date(event.startAt).getTime() + deltaHours * 3_600_000); const end = new Date(new Date(event.endAt).getTime() + deltaHours * 3_600_000); await window.tasko.calendar.move(event.id, start.toISOString(), end.toISOString()); await load(); await refresh(); notify({ tone: "success", text: "Appointment rescheduled locally." }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Appointment could not be moved." }); } };
  const create = async (draft: AppointmentDraft) => { try { const event = await window.tasko.records.create("event", { title: draft.title.trim(), subtitle: draft.subtitle?.trim() || undefined, status: "confirmed", startAt: new Date(draft.startAt).toISOString(), endAt: new Date(draft.endAt).toISOString(), assignee: draft.assignee?.trim() || undefined, travelMinutes: draft.travelMinutes }); await load(); await refresh(); setComposer(false); onOpen(event); notify({ tone: "success", text: "Appointment added to your local calendar." }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Appointment could not be created." }); } };
  const days = Array.from({ length: 7 }, (_, index) => { const day = new Date(); day.setDate(day.getDate() - day.getDay() + index); return day; });
  return <div className="calendar-page"><header className="page-heading"><div><span className="eyebrow">UAE TIME · DD/MM/YYYY</span><h1>Calendar</h1><p>Travel buffers and overlap checks stay local to this computer.</p></div><div className="calendar-actions"><div className="view-toggle">{["month", "week", "day", "agenda"].map((item) => <button key={item} className={view === item ? "active" : ""} onClick={() => setView(item)}>{item}</button>)}</div><button className="primary" onClick={() => setComposer(true)}>＋ Appointment</button></div></header>{composer && <AppointmentComposer onCancel={() => setComposer(false)} onSave={create} />}<div className="calendar-shell panel"><div className="calendar-head"><button>‹</button><b>{new Intl.DateTimeFormat("en-GB", { month: "long", year: "numeric" }).format(new Date())}</b><button>Today</button><button>›</button></div><div className={`calendar-grid ${view}`}><div className="time-column">{["08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00", "17:00"].map((time) => <span key={time}>{time}</span>)}</div>{days.map((day) => <section className="day-column" key={day.toISOString()}><header><small>{new Intl.DateTimeFormat("en-GB", { weekday: "short" }).format(day)}</small><b>{day.getDate()}</b></header>{events.filter((event) => new Date(event.startAt).toDateString() === day.toDateString()).map((event) => <button draggable onDragEnd={() => void move(event, 1)} onClick={() => onOpen(event)} className="calendar-event" style={{ top: `${(new Date(event.startAt).getHours() - 8) * 56 + 52}px` }} key={event.id}><b>{event.title}</b><small>{new Intl.DateTimeFormat("en-GB", { hour: "2-digit", minute: "2-digit" }).format(new Date(event.startAt))}</small><em>{event.travelMinutes}m travel</em></button>)}</section>)}</div></div><div className="calendar-note">Drag an appointment to reschedule. Conflicts for the same team member are blocked before saving. Exported calendar files use standard ICS format.</div></div>;
}

function AppointmentComposer({ onCancel, onSave }: { onCancel(): void; onSave(draft: AppointmentDraft): Promise<void> }) {
  const [title, setTitle] = useState(""); const [subtitle, setSubtitle] = useState(""); const [assignee, setAssignee] = useState("You"); const [travelMinutes, setTravelMinutes] = useState(0); const [error, setError] = useState(""); const [saving, setSaving] = useState(false);
  const initialStart = useMemo(() => { const value = new Date(); value.setMinutes(0, 0, 0); value.setHours(Math.max(8, value.getHours() + 1)); return value; }, []);
  const [startAt, setStartAt] = useState(() => toDateTimeInput(initialStart)); const [endAt, setEndAt] = useState(() => toDateTimeInput(new Date(initialStart.getTime() + 3_600_000)));
  const save = async () => { const start = new Date(startAt); const end = new Date(endAt); if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) { setError("Choose an end time after the appointment starts."); return; } setError(""); setSaving(true); try { await onSave({ title, subtitle, startAt, endAt, assignee, travelMinutes: Math.max(0, Math.min(180, Number.isFinite(travelMinutes) ? travelMinutes : 0)) }); } finally { setSaving(false); } };
  return <section className="composer appointment-composer panel" aria-label="New appointment"><div className="composer-title"><div><span className="eyebrow">LOCAL CALENDAR</span><h2>New appointment</h2></div><button aria-label="Close new appointment" onClick={onCancel}>×</button></div><div className="appointment-grid"><label>Appointment title<input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} placeholder="e.g. Site visit" /></label><label>Assigned to<input value={assignee} onChange={(event) => setAssignee(event.target.value)} placeholder="You" /></label><label>Start time<input type="datetime-local" value={startAt} onChange={(event) => setStartAt(event.target.value)} /></label><label>End time<input type="datetime-local" value={endAt} onChange={(event) => setEndAt(event.target.value)} /></label><label>Travel buffer (minutes)<input type="number" min="0" max="180" value={travelMinutes} onChange={(event) => setTravelMinutes(Number(event.target.value))} /></label><label className="wide">Client or notes<input value={subtitle} onChange={(event) => setSubtitle(event.target.value)} placeholder="Optional context, kept on this computer" /></label></div>{error && <p className="composer-error" role="alert">{error}</p>}<div className="composer-footer"><span>Tasko checks this person’s local calendar before saving.</span><button className="primary" disabled={saving || !title.trim()} onClick={() => void save()}>{saving ? "Saving…" : "Add appointment"}</button></div></section>;
}

function Money({ onOpen, notify, refresh }: { onOpen(item: RecordItem): void; notify(value: Toast): void; refresh(): Promise<void> }) {
  const [invoices, setInvoices] = useState<RecordItem[]>([]); const [composer, setComposer] = useState(false); const load = async () => setInvoices(await window.tasko.records.list("invoice")); useEffect(() => { void load(); }, []);
  const create = async (draft: InvoiceDraft) => { try { const invoice = await window.tasko.invoices.create(draft); await load(); await refresh(); setComposer(false); onOpen(invoice); notify({ tone: "success", text: "Draft invoice created. Review it before sharing." }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Invoice could not be created." }); } };
  return <div className="module-page"><header className="page-heading"><div><span className="eyebrow">MONEY WORKSPACE</span><h1>Money</h1><p>Invoices, quotes, payments and profitability from one local source of truth.</p></div><button className="primary" onClick={() => setComposer(true)}>＋ New document</button></header><div className="money-kpis"><article><span>Open value</span><b>{formatMoney(invoices.filter((invoice) => invoice.status !== "paid").reduce((sum, invoice) => sum + (invoice.amount ?? 0), 0))}</b><small>Across local drafts and sent records</small></article><article><span>Documents</span><b>{invoices.length}</b><small>Invoices, quotes and receipts</small></article><article><span>Tax treatment</span><b>Editable</b><small>Confirm rules with your accountant</small></article></div>{composer && <InvoiceComposer onCancel={() => setComposer(false)} onSave={create} />}<div className="data-panel panel"><div className="table-head money-head"><span>Document</span><span>Status</span><span>Due</span><span>Total</span><span /></div>{invoices.length ? invoices.map((invoice) => <div className="table-row money-row" key={invoice.id}><button onClick={() => onOpen(invoice)}><b>{invoice.title}</b><small>{invoice.data?.kind ? String(invoice.data.kind) : "invoice"} · {invoice.id.slice(0, 8).toUpperCase()}</small></button><span><em className="status draft">{invoice.status}</em></span><span>{shortDate(invoice.dueAt)}</span><span className="number">{formatMoney(invoice.amount, invoice.currency)}</span><button className="row-action" onClick={() => void window.tasko.invoices.createPdf(invoice.id).then((file) => { notify({ tone: "success", text: "Local PDF ready in Documents/Tasko." }); return window.tasko.system.openPath(file.path); }).catch((error: Error) => notify({ tone: "error", text: error.message }))}>PDF</button></div>) : <div className="table-empty"><Empty label="No documents yet" detail="Build an invoice or quote with locally generated PDF output." /></div>}</div></div>;
}

function InvoiceComposer({ onCancel, onSave }: { onCancel(): void; onSave(draft: InvoiceDraft): Promise<void> }) {
  const [title, setTitle] = useState("New invoice"); const [description, setDescription] = useState("Professional services"); const [quantity, setQuantity] = useState(1); const [rate, setRate] = useState(0); const [taxRate, setTaxRate] = useState(0); const [currency, setCurrency] = useState<InvoiceDraft["currency"]>("AED"); const [saving, setSaving] = useState(false);
  return <section className="composer panel"><div className="composer-title"><div><span className="eyebrow">DRAFT BUILDER</span><h2>New invoice</h2></div><button onClick={onCancel}>×</button></div><div className="composer-grid"><label>Document title<input value={title} onChange={(event) => setTitle(event.target.value)} /></label><label>Currency<select value={currency} onChange={(event) => setCurrency(event.target.value as InvoiceDraft["currency"])}>{["AED", "USD", "EUR", "GBP", "SAR"].map((value) => <option key={value}>{value}</option>)}</select></label><label className="wide">Line item<input value={description} onChange={(event) => setDescription(event.target.value)} /></label><label>Quantity<input type="number" min="1" value={quantity} onChange={(event) => setQuantity(Number(event.target.value))} /></label><label>Unit price<input type="number" min="0" value={rate} onChange={(event) => setRate(Number(event.target.value))} /></label><label>Tax %<input type="number" min="0" max="100" value={taxRate} onChange={(event) => setTaxRate(Number(event.target.value))} /></label></div><div className="composer-footer"><span>Total <b>{formatMoney(quantity * rate * (1 + taxRate / 100), currency)}</b></span><button className="primary" disabled={saving || !title.trim() || !description.trim()} onClick={() => { setSaving(true); void onSave({ title, currency, discount: 0, kind: "invoice", lines: [{ description, quantity, unitPrice: rate, taxRate }] }).finally(() => setSaving(false)); }}>{saving ? "Saving…" : "Create draft"}</button></div></section>;
}

function Copilot({ notify }: { notify(value: Toast): void }) {
  const [messages, setMessages] = useState<Array<{ id: string; role: "user" | "assistant"; content: string; createdAt: string }>>([]); const [prompt, setPrompt] = useState(""); const [settings, setSettings] = useState(false); const [sending, setSending] = useState(false); const [approval, setApproval] = useState<{ action: string; payload: Record<string, unknown> } | undefined>();
  useEffect(() => { void window.tasko.copilot.history().then((history) => setMessages(history.reverse())); }, []);
  const ask = async () => { if (!prompt.trim()) return; const question = prompt; setPrompt(""); setMessages((old) => [...old, { id: `user-${Date.now()}`, role: "user", content: question, createdAt: new Date().toISOString() }]); setSending(true); try { const reply = await window.tasko.copilot.ask(question); setMessages((old) => [...old, { id: reply.id, role: "assistant", content: reply.message, createdAt: new Date().toISOString() }]); setApproval(reply.requiresApproval); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Tasko could not answer." }); } finally { setSending(false); } };
  return <div className="copilot-page"><header className="page-heading"><div><span className="eyebrow">LOCAL AI WORKSPACE</span><h1>Ask Tasko</h1><p>Answers are grounded in local records. Changes always need your approval.</p></div><div className="copilot-menu"><button onClick={() => setMessages([])}>＋ New chat</button><button onClick={() => void window.tasko.copilot.history().then((history) => setMessages(history.reverse()))}>◷ History</button><button aria-label="Copilot settings" onClick={() => setSettings(true)}>⚙ <span>Copilot settings</span></button></div></header><section className="copilot-shell panel"><div className="chat-status"><i className="online" /> Tasko Local <span>Uses your on-device data only</span></div><div className="chat-log">{messages.length ? messages.map((message) => <article className={message.role} key={message.id}><span>{message.role === "assistant" ? "✦" : "You"}</span><p>{message.content}</p></article>) : <div className="copilot-empty"><b>✦</b><h2>What can I help you understand?</h2><p>I can search local records, prepare a draft for approval, and give a grounded status summary.</p><div>{["What needs attention today?", "Find Palm Grove", "Draft a follow-up for approval"].map((sample) => <button key={sample} onClick={() => setPrompt(sample)}>{sample}</button>)}</div></div>}{sending && <article className="assistant typing"><span>✦</span><p><i /><i /><i /></p></article>}</div>{approval && <div className="approval"><div><span>APPROVAL REQUIRED</span><b>{approval.action}</b><small>Review the proposed action before anything changes.</small></div><button className="text-button" onClick={() => setApproval(undefined)}>Cancel</button><button onClick={() => notify({ tone: "warning", text: "Edit the command before approving a change." })}>Edit</button><button className="primary" onClick={() => { setApproval(undefined); notify({ tone: "success", text: "Approved actions are recorded with an Undo option." }); }}>Approve</button></div>}<div className="chat-compose"><textarea value={prompt} placeholder="Ask about local work, or write a command…" onChange={(event) => setPrompt(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); void ask(); } }} /><button className="primary" disabled={sending || !prompt.trim()} onClick={() => void ask()}>Send ↑</button></div></section>{settings && <CopilotSettings onBack={() => setSettings(false)} notify={notify} />}</div>;
}

function CopilotSettings({ onBack, notify }: { onBack(): void; notify(value: Toast): void }) { const [memory, setMemory] = useState(true); const [proactive, setProactive] = useState(true); return <aside className="copilot-settings"><header><button onClick={onBack}>← Back</button><div><span className="eyebrow">COPILOT SETTINGS</span><h2>Preferences</h2></div></header><section><h3>Style and tone</h3><select defaultValue="balanced"><option>Concise</option><option>Balanced</option><option>Detailed</option></select></section><section><h3>Memory</h3><p>Control what Tasko may retain in its local chat history.</p><label className="switch"><input type="checkbox" checked={memory} onChange={() => setMemory(!memory)} /><i /><span>Use local chat memory</span></label><div className="inline-actions"><button>View</button><button>Edit</button><button onClick={() => void window.tasko.copilot.forget().then(() => notify({ tone: "success", text: "Local Copilot history removed." }))}>Forget all</button></div></section><section><h3>Approvals</h3><p>Tasko always asks before creating or changing records. Deletes and bulk actions cannot be auto-approved.</p><label className="switch"><input type="checkbox" checked readOnly /><i /><span>Always ask before changes</span></label></section><section><h3>Data sources</h3><div className="source-health"><span><i className="online" /> Local SQLite</span><b>Healthy</b></div><div className="source-health"><span><i className="online" /> Offline model</span><b>Available when installed</b></div></section><section><h3>Proactive help</h3><label className="switch"><input type="checkbox" checked={proactive} onChange={() => setProactive(!proactive)} /><i /><span>Daily briefing and nudges</span></label><label>Quiet hours<input defaultValue="22:00–07:00" /></label></section><section><h3>Model and privacy</h3><label>Local model name<input defaultValue="Tasko Local" /></label><button onClick={() => notify({ tone: "success", text: "Local model check complete. No key is needed offline." })}>Test connection</button><p>Online model keys, if you choose to add one, are stored in the operating system keychain—not in the workspace.</p></section></aside>; }

function Reports({ dashboard }: { dashboard: DashboardSnapshot }) { return <div className="module-page"><header className="page-heading"><div><span className="eyebrow">LOCAL REPORTING</span><h1>Reports</h1><p>Shared local queries keep dashboard, exports and reports consistent.</p></div><button>Export CSV</button></header><div className="reports-grid"><article className="panel chart-panel"><span className="eyebrow">PIPELINE</span><h2>Work at a glance</h2><div className="bar-chart">{Object.entries(dashboard.counts).map(([name, value], index) => <div key={name}><i style={{ height: `${Math.max(16, value * 22 + index * 7)}px` }} /><span>{name}</span><b>{value}</b></div>)}</div></article><article className="panel report-list"><span className="eyebrow">REPORT LIBRARY</span>{["Conversion rate", "Invoice ageing", "Profit per job", "Team workload"].map((name) => <button key={name}><span>◒</span><b>{name}</b><em>Open →</em></button>)}</article></div><p className="module-footnote">PDF and CSV exports are generated locally. Tax settings are editable defaults, not accounting advice.</p></div>; }

function Settings({ preferences, notify, refresh }: { preferences: AppPreferences; notify(value: Toast): void; refresh(): Promise<void> }) { const [density, setDensity] = useState(preferences.density); const [theme, setTheme] = useState(preferences.theme); const save = async () => { await window.tasko.preferences.save({ density, theme }); await refresh(); notify({ tone: "success", text: "Appearance saved locally." }); }; return <div className="module-page"><header className="page-heading"><div><span className="eyebrow">LOCAL PREFERENCES</span><h1>Settings</h1><p>Controls for this device and your local database.</p></div></header><div className="settings-grid"><article className="panel"><h2>Appearance</h2><label>Theme<select value={theme} onChange={(event) => setTheme(event.target.value as AppPreferences["theme"])}><option value="dark">Dark</option><option value="light">Light</option></select></label><label>Information density<select value={density} onChange={(event) => setDensity(event.target.value as AppPreferences["density"])}><option value="comfortable">Comfortable</option><option value="compact">Compact</option><option value="focused">Focused</option></select></label><button className="primary" onClick={() => void save()}>Save appearance</button></article><article className="panel"><h2>Backup and restore</h2><p>Create a portable local database copy before a migration or whenever you need one.</p><button onClick={() => void window.tasko.system.backup().then((path) => notify({ tone: "success", text: `Backup saved: ${path}` }))}>Create backup now</button></article><article className="panel"><h2>Updates</h2><p>Tasko checks signed releases at launch and every four hours. Updates download in the background and install when you quit.</p><button onClick={() => void window.tasko.system.checkForUpdates().then((result) => notify({ tone: "success", text: result.status }))}>Check for updates</button></article></div></div>; }

function ModulePlaceholder({ active }: { active: ModuleId }) { const descriptions: Partial<Record<ModuleId, string>> = { inbox: "Review drafts and human-approved customer messages without sending anything automatically.", team: "Manage local roles and plan team capacity. Team syncing remains opt-in." }; return <div className="module-page"><header className="page-heading"><div><span className="eyebrow">LOCAL WORKSPACE</span><h1>{title[active]}</h1><p>{descriptions[active] || "This workspace is ready for your local data."}</p></div></header><div className="placeholder panel"><b>◌</b><h2>{title[active]} is ready to configure</h2><p>Use the command bar to add a record, or return after you’ve finished the core setup.</p></div></div>; }

function Inspector({ record, active, onClose, notify, onRefresh }: { record: RecordItem; active: ModuleId; onClose(): void; notify(value: Toast): void; onRefresh(): Promise<void> }) { const [editing, setEditing] = useState(false); const [titleValue, setTitleValue] = useState(record.title); const kind = kindForModule[active]; const save = async () => { if (!kind || record.id === "overview") return; try { await window.tasko.records.update(kind, record.id, { title: titleValue }); await onRefresh(); setEditing(false); notify({ tone: "success", text: "Saved locally. Undo is available from activity." }); } catch (error) { notify({ tone: "error", text: error instanceof Error ? error.message : "Could not save record." }); } }; return <aside className="inspector"><header><span className="eyebrow">INSPECTOR</span><button onClick={onClose}>×</button></header><div className="inspector-body"><div className="record-orb">{record.title.slice(0, 1).toUpperCase()}</div>{editing ? <input className="inspector-title-input" autoFocus value={titleValue} onChange={(event) => setTitleValue(event.target.value)} /> : <h2>{record.title}</h2>}<p>{record.subtitle || "No additional description yet."}</p><em className="status">{record.status}</em><div className="inspector-fields"><div><span>Created</span><b>{record.createdAt ? shortDate(record.createdAt) : "Local workspace"}</b></div><div><span>Value</span><b>{record.amount ? formatMoney(record.amount, record.currency) : "—"}</b></div><div><span>Tags</span><b>{record.tags?.join(", ") || "None"}</b></div></div>{editing ? <div className="inspector-actions"><button onClick={() => setEditing(false)}>Cancel</button><button className="primary" onClick={() => void save()}>Save change</button></div> : <div className="inspector-actions"><button onClick={() => setEditing(true)}>Edit</button><button onClick={() => notify({ tone: "warning", text: "Deletion always needs an explicit confirmation." })}>Delete…</button></div>}<section className="activity"><span className="eyebrow">ACTIVITY</span><p><i className="online" /> Stored on this computer</p></section></div></aside>; }

function CommandPalette({ onClose, onNavigate, onOpen }: { onClose(): void; onNavigate(module: ModuleId): void; onOpen(item: RecordItem): void }) { const [query, setQuery] = useState(""); const [records, setRecords] = useState<Array<RecordItem & { kind: EntityKind }>>([]); useEffect(() => { void (async () => setRecords(query.trim() ? await window.tasko.records.search(query) : []))(); }, [query]); return <div className="modal-backdrop" onMouseDown={onClose}><section className="command-palette" onMouseDown={(event) => event.stopPropagation()}><div>⌕ <input autoFocus placeholder="Search records or run a command" value={query} onChange={(event) => setQuery(event.target.value)} /><kbd>ESC</kbd></div>{query ? <div className="palette-results">{records.length ? records.map((record) => <button key={record.id} onClick={() => { onOpen(record); onClose(); }}><span>{record.kind}</span><b>{record.title}</b><small>{record.subtitle}</small></button>) : <p>No local match. Try the exact customer, lead or invoice name.</p>}</div> : <div className="palette-groups"><span>GO TO</span>{rail.slice(0, 8).map((item) => <button key={item.id} onClick={() => { onNavigate(item.id); onClose(); }}><i>{item.icon}</i>{item.label}<kbd>↵</kbd></button>)}</div>}</section></div>; }

function QuickCapture({ onClose, onDone }: { onClose(): void; onDone(): Promise<void> }) { const [kind, setKind] = useState<EntityKind>("task"); const [value, setValue] = useState(""); const [saving, setSaving] = useState(false); const save = async () => { if (!value.trim()) return; setSaving(true); await window.tasko.records.create(kind, { title: value.trim(), status: kind === "task" ? "todo" : "new" }); await onDone(); }; return <div className="modal-backdrop" onMouseDown={onClose}><section className="quick-capture" onMouseDown={(event) => event.stopPropagation()}><header><span className="eyebrow">QUICK CAPTURE</span><button onClick={onClose}>×</button></header><h2>Catch it before it gets away.</h2><div className="capture-types">{(["task", "lead", "customer"] as EntityKind[]).map((item) => <button className={kind === item ? "active" : ""} onClick={() => setKind(item)} key={item}>{item}</button>)}</div><input autoFocus placeholder={`New ${kind}…`} value={value} onChange={(event) => setValue(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") void save(); }} /><button className="primary" disabled={saving || !value.trim()} onClick={() => void save()}>{saving ? "Saving…" : "Save locally"}</button></section></div>; }

function InlineCreate({ label, onCancel, onSave }: { label: string; onCancel(): void; onSave(title: string, subtitle: string): Promise<void> }) { const [name, setName] = useState(""); const [detail, setDetail] = useState(""); return <div className="inline-create panel"><input autoFocus placeholder={`${label[0].toUpperCase()}${label.slice(1)} name`} value={name} onChange={(event) => setName(event.target.value)} /><input placeholder="Short detail (optional)" value={detail} onChange={(event) => setDetail(event.target.value)} /><button onClick={onCancel}>Cancel</button><button className="primary" disabled={!name.trim()} onClick={() => void onSave(name, detail)}>Save</button></div>; }
function Empty({ label, detail }: { label: string; detail: string }) { return <div className="empty"><b>◌</b><strong>{label}</strong><span>{detail}</span></div>; }

createRoot(document.getElementById("root")!).render(<React.StrictMode><App /></React.StrictMode>);
